# shared filters: entity, region, date; chips; URL; persistence across reload; KPIs + charts + grids all move
k0 = txt(pg, '[data-kpi="ov-cash"] .kpi-val'); t0 = ev(pg, "() => document.querySelector('[data-chart=\"ov-exposure\"] table.dv-table tbody').textContent")
pg.click('#ftbEntityT'); pg.wait_for_timeout(200); pg.click('#ftbEntityM [data-value="NWG-US"]'); pg.wait_for_timeout(700)
k1 = txt(pg, '[data-kpi="ov-cash"] .kpi-val'); t1 = ev(pg, "() => document.querySelector('[data-chart=\"ov-exposure\"] table.dv-table tbody').textContent")
check('entity filter moves the cash KPI', k0 != k1, [k0, k1])
check('entity filter re-renders the exposure chart (its table spine changes)', t0 != t1, [t0[:80], t1[:80]])
check('entity filter is written to the URL', 'entity=NWG-US' in pg.url, pg.url)
check('an applied-filter chip appears', 'Northwind Americas' in txt(pg, '#ftbChips'), txt(pg, '#ftbChips'))
check('toolbar state is "filtered"', ev(pg, "() => document.getElementById('ftb').getAttribute('data-ftb-state')") in ('filtered', 'empty'))
pg.click('#ftbDaysT'); pg.wait_for_timeout(200); pg.click('#ftbDaysM [data-value="7"]'); pg.wait_for_timeout(700)
n7 = ev(pg, "() => document.querySelectorAll('[data-chart=\"ov-liqtrend\"] table.dv-table tbody tr').length")
check('date filter to 7 days redraws the 30-day series as 7 points', n7 == 7, n7)
pg.reload(); pg.wait_for_timeout(1400)
check('entity and date survive a reload (dropdown labels)', txt(pg, '#ftbEntityT .ddval') == 'Northwind Americas Inc.' and txt(pg, '#ftbDaysT .ddval') == 'Last 7 days', [txt(pg, '#ftbEntityT .ddval'), txt(pg, '#ftbDaysT .ddval')])
pg.click('a.sn-link[data-nav="accounts"]'); pg.wait_for_timeout(900)
rows = ev(pg, "() => [...document.querySelectorAll('#dg-tx tbody tr')].map(r => r.cells[2] && r.cells[2].innerText)")
check('filters carry across views: every transaction row is the chosen entity', rows and all(r == 'Northwind Americas Inc.' for r in rows), rows[:3])
pg.click('#ftbRegionT'); pg.wait_for_timeout(200); pg.click('#ftbRegionM [data-value="Europe"]'); pg.wait_for_timeout(700)
check('choosing a region that excludes the entity resets the entity to all', txt(pg, '#ftbEntityT .ddval') == 'All entities', txt(pg, '#ftbEntityT .ddval'))
rg = ev(pg, "() => [...new Set([...document.querySelectorAll('#dg-acc tbody tr')].map(r => r.cells[3] && r.cells[3].innerText))]")
check('region filter reaches the accounts grid', rg == ['Europe'], rg)
pg.click('#ftbChips button[data-chip="days"]'); pg.wait_for_timeout(500)
pg.fill('#ftbQ', 'Atlas'); pg.wait_for_timeout(700)
cp = ev(pg, "() => [...document.querySelectorAll('#dg-tx tbody tr')].map(r => r.cells.length > 3 ? r.cells[3].innerText : 'EMPTY:' + r.innerText)")
check('search filters the transactions grid', cp and all('Atlas' in c for c in cp), cp[:3])
pg.fill('#ftbQ', 'zzzz-no-such'); pg.wait_for_timeout(700)
check('a search with no match shows the grid empty state and the toolbar "empty" state', 'No transactions match' in txt(pg, '#dg-tx tbody') and ev(pg, "() => document.getElementById('ftb').getAttribute('data-ftb-state')") == 'empty', txt(pg, '#dg-tx tbody'))
pg.fill('#ftbQ', 'Atlas'); pg.wait_for_timeout(700)
check('search is written to the URL', 'q=Atlas' in pg.url, pg.url)
pg.click('#ftbChips button[data-chip="q"]'); pg.wait_for_timeout(500)
check('removing the search chip clears the search box', ev(pg, "() => document.getElementById('ftbQ').value") == '')
pg.click('.ftb-clear [data-ftb-clear]'); pg.wait_for_timeout(700)
check('Clear all resets every filter', ev(pg, "() => document.getElementById('ftb').getAttribute('data-ftb-state')") == 'no-filters' and '?' not in pg.url.split('#')[1], pg.url)
with pg.expect_download() as d:
    pg.click('#ftbExportT'); pg.wait_for_timeout(200); pg.click('#ftbExportM [data-value="csv"]')
dl = d.value; path = W + '/proof/export-sample.csv'; dl.save_as(path)
lines = open(path).read().splitlines()
check('Export CSV downloads the visible grid (header + rows)', len(lines) > 10 and lines[0].startswith('id,'), [dl.suggested_filename, len(lines), lines[0]])
